class ListNode(var `val`: Int) {
    var next: ListNode? = null
}

fun hasCycle(head: ListNode?): Boolean {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
        if (slow === fast) return true     // pointers met inside a cycle
    }
    return false                           // fast reached the end
}
// Time: O(n)   Space: O(1)

fun middleNode(head: ListNode?): ListNode? {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
    }
    return slow    // second middle when the length is even
}
// Time: O(n)   Space: O(1)

fun detectCycle(head: ListNode?): ListNode? {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
        if (slow === fast) {
            // Phase 2: reset one pointer to head, move both one step
            var start = head
            while (start !== slow) {
                start = start!!.next
                slow = slow!!.next
            }
            return start      // cycle entrance
        }
    }
    return null
}
// Time: O(n)   Space: O(1)

fun cycleLength(head: ListNode?): Int {
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
        if (slow === fast) {
            var length = 1
            var cur = slow!!.next
            while (cur !== slow) {
                cur = cur!!.next
                length++
            }
            return length
        }
    }
    return 0
}
// Time: O(n)   Space: O(1)

fun isHappy(n: Int): Boolean {
    fun next(x: Int): Int {
        var num = x
        var sum = 0
        while (num > 0) {
            val d = num % 10
            sum += d * d
            num /= 10
        }
        return sum
    }

    var slow = n
    var fast = next(n)
    while (fast != 1 && slow != fast) {
        slow = next(slow)
        fast = next(next(fast))
    }
    return fast == 1
}
// Time: O(log n)   Space: O(1)
// The sequence either reaches 1 or enters a cycle

fun findDuplicate(nums: IntArray): Int {
    // Treat nums[i] as a pointer to index nums[i]
    var slow = nums[0]
    var fast = nums[0]
    do {
        slow = nums[slow]
        fast = nums[nums[fast]]
    } while (slow != fast)

    slow = nums[0]
    while (slow != fast) {
        slow = nums[slow]
        fast = nums[fast]
    }
    return slow
}
// Time: O(n)   Space: O(1)
// Array has n + 1 numbers in range 1..n, so a cycle must exist

fun removeNthFromEnd(head: ListNode?, n: Int): ListNode? {
    val dummy = ListNode(0)
    dummy.next = head
    var fast: ListNode? = dummy
    var slow: ListNode? = dummy
    repeat(n + 1) { fast = fast?.next }       // create a gap of n nodes
    while (fast != null) {
        fast = fast?.next
        slow = slow?.next
    }
    slow!!.next = slow.next?.next             // skip the target node
    return dummy.next
}
// Time: O(n)   Space: O(1)
// Gap technique: pointers move at the same speed

fun isPalindrome(head: ListNode?): Boolean {
    // 1. Find the middle
    var slow = head
    var fast = head
    while (fast?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
    }
    // 2. Reverse the second half
    var prev: ListNode? = null
    var cur = slow
    while (cur != null) {
        val next = cur.next
        cur.next = prev
        prev = cur
        cur = next
    }
    // 3. Compare both halves
    var left = head
    var right = prev
    while (right != null) {
        if (left!!.`val` != right.`val`) return false
        left = left.next
        right = right.next
    }
    return true
}
// Time: O(n)   Space: O(1)

fun reorderList(head: ListNode?) {
    if (head?.next == null) return
    // 1. Find the middle
    var slow = head
    var fast = head
    while (fast?.next != null && fast.next?.next != null) {
        slow = slow!!.next
        fast = fast.next!!.next
    }
    // 2. Reverse the second half
    var prev: ListNode? = null
    var cur = slow!!.next
    slow.next = null
    while (cur != null) {
        val next = cur.next
        cur.next = prev
        prev = cur
        cur = next
    }
    // 3. Merge alternately: L0, Ln, L1, Ln-1, ...
    var first = head
    var second = prev
    while (second != null) {
        val t1 = first!!.next
        val t2 = second.next
        first.next = second
        second.next = t1
        first = t1
        second = t2
    }
}
// Time: O(n)   Space: O(1)

fun circularArrayLoop(nums: IntArray): Boolean {
    val n = nums.size
    fun next(i: Int): Int = ((i + nums[i]) % n + n) % n

    for (i in nums.indices) {
        var slow = i
        var fast = i
        val forward = nums[i] > 0
        while (true) {
            val s = next(slow)
            if ((nums[s] > 0) != forward || s == slow) break
            val f1 = next(fast)
            if ((nums[f1] > 0) != forward || f1 == fast) break
            val f2 = next(f1)
            if ((nums[f2] > 0) != forward || f2 == f1) break
            slow = s
            fast = f2
            if (slow == fast) return true
        }
    }
    return false
}
// Time: O(n²) worst case here   Space: O(1)
// Rule: a valid loop has the same direction and length > 1

